const fs = require('fs');

function readInput() {
  try {
    return fs.readFileSync(0, 'utf8');
  } catch (e) {
    try {
      return fs.readFileSync('/dev/stdin', 'utf8');
    } catch (e2) {
      return '';
    }
  }
}

const lines = readInput().split(/\r?\n/).filter(l => l.trim().length > 0);

let ptr = 0;
const header = lines[ptr++].trim().split(/\s+/);
const N = parseInt(header[0], 10);
const Q = parseInt(header[1], 10);

const SZ = N + 2; // grid com borda de células mortas (padding)
let cur = new Uint8Array(SZ * SZ);
for (let i = 0; i < N; i++) {
  const row = lines[ptr++].trim();
  const base = (i + 1) * SZ;
  for (let j = 0; j < N; j++) {
    cur[base + j + 1] = row.charCodeAt(j) === 49 ? 1 : 0;
  }
}

let nxt = new Uint8Array(SZ * SZ);

for (let s = 0; s < Q; s++) {
  for (let i = 1; i <= N; i++) {
    const base = i * SZ;
    const up = base - SZ;
    const down = base + SZ;
    for (let j = 1; j <= N; j++) {
      const jL = j - 1, jR = j + 1;
      const cnt =
        cur[up + jL] + cur[up + j] + cur[up + jR] +
        cur[base + jL] + cur[base + jR] +
        cur[down + jL] + cur[down + j] + cur[down + jR];
      // viva sobrevive com 2 ou 3 vizinhos; morta nasce com exatamente 3
      nxt[base + j] = (cnt === 3 || (cnt === 2 && cur[base + j] === 1)) ? 1 : 0;
    }
  }
  const t = cur; cur = nxt; nxt = t;
}

const out = [];
for (let i = 0; i < N; i++) {
  const base = (i + 1) * SZ;
  let row = '';
  for (let j = 0; j < N; j++) row += cur[base + j + 1];
  out.push(row);
}
process.stdout.write(out.join('\n') + '\n');
